"""Writes the auto-generated metrics section of docs/MODEL_CARD.md.

Everything between the AUTO-START / AUTO-END markers is regenerated on every
`make train`; hand-written sections outside the markers are preserved.
"""

from __future__ import annotations

from pathlib import Path
from typing import Any

from app.config import get_settings
from app.ml.registry import ModelBundle

START = "<!-- AUTO-START: generated by app.ml.model_card, do not edit by hand -->"
END = "<!-- AUTO-END -->"


def _f(x: Any, nd: int = 3) -> str:
    return "—" if x is None else f"{x:.{nd}f}"


def render(bundle: ModelBundle) -> str:
    m = bundle.metrics
    r, u, d = m["risk"], m["uplift"], m["data"]
    lines = [
        START,
        f"### Generated metrics — model version `{bundle.version}`",
        "",
        f"Training data: {d['n_history']:,} simulated historical abnormal results (seed {d['seed']}); "
        f"train/val/test = {d['n_train']:,}/{d['n_val']:,}/{d['n_test']:,}. Historical return rate without "
        f"outreach {d['historical_return_rate_no_outreach']:.1%}, with randomised outreach {d['historical_return_rate_outreach']:.1%}.",
        "",
        "**Drop-off risk model** (LightGBM + isotonic calibration, no-outreach test arm)",
        "",
        "| Metric | Value |",
        "|---|---|",
        f"| AUROC | {_f(r['auroc'])} |",
        f"| AUPRC | {_f(r['auprc'])} |",
        f"| Brier score | {_f(r['brier'])} |",
        "",
        "Per language group:",
        "",
        "| Group | n | AUROC | Brier | TPR of high-risk flag |",
        "|---|---|---|---|---|",
    ]
    for g, gm in r["by_language"].items():
        lines.append(f"| {g} | {gm['n']} | {_f(gm['auroc'])} | {_f(gm['brier'])} | {_f(gm['tpr_high_risk'])} |")
    lines += ["", "Per insurance tier:", "", "| Tier | n | AUROC | Brier |", "|---|---|---|---|"]
    for g, gm in r["by_insurance_tier"].items():
        lines.append(f"| {g} | {gm['n']} | {_f(gm['auroc'])} | {_f(gm['brier'])} |")
    lines += [
        "",
        "**Uplift model** (T-learner, two LightGBM classifiers)",
        "",
        "| Ranking | AUUC vs true effect | Observed Qini AUUC |",
        "|---|---|---|",
    ]
    for k in ("uplift", "risk", "random"):
        lines.append(f"| {k} | {_f(u['auuc_true'][k], 4)} | {_f(u['qini_auuc_observed'][k], 4)} |")
    lines += [
        "",
        f"Correlation of predicted with true uplift (test): {_f(u['corr_with_true_tau'])}. "
        f"Mean true uplift {_f(u['mean_true_tau'])}, mean predicted {_f(u['mean_pred_tau'])}.",
        "AUUC is normalised so random targeting ≈ 0. The observed Qini uses real (simulated) outcomes "
        "and is noisier; the true-effect AUUC uses the generator's known effect and is the acceptance metric.",
        END,
    ]
    return "\n".join(lines)


def write_model_card(bundle: ModelBundle) -> Path:
    path = Path(get_settings().docs_dir) / "MODEL_CARD.md"
    block = render(bundle)
    if path.exists():
        text = path.read_text()
        if START in text and END in text:
            pre = text.split(START)[0]
            post = text.split(END, 1)[1]
            path.write_text(pre + block + post)
            return path
        path.write_text(text.rstrip() + "\n\n## Metrics\n\n" + block + "\n")
        return path
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("# WASL Model Card\n\n## Metrics\n\n" + block + "\n")
    return path
